/* Token Launch Radar -- dashboard stylesheet. */

:root {
  --bg: #f2f5f3;
  --panel: #ffffff;
  --ink: #16211c;
  --muted: #5f6f67;
  --accent: #0f7a5a;
  --neg: #b23b2e;
  --line: #d8e2dc;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
